<template><view class="shop-page"><BusinessPageHeader title="收银台" fallback="/pages/selection/index"/><view class="shop-body"><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="order"><view class="shop-cash-total"><text class="shop-muted">待支付金额</text><view class="shop-price">¥{{money(order.payableAmount)}}</view></view><view class="shop-title">支付详情</view><view class="shop-card"><view class="shop-row"><text>平台</text><text>脑商收银</text></view><view class="shop-row"><text>收款编号</text><text>{{order.orderNo}}</text></view><view class="shop-row"><text>剩余支付时间</text><text>{{remaining}}</text></view></view><view class="shop-title">支付方式</view><view class="shop-card"><button v-for="item in channels" :key="item.id" class="shop-channel" :class="{selected:channel===item.id}" :disabled="busy||!!attemptId" @click="channel=item.id"><view class="shop-payment-mark" :class="`payment-${item.id}`">{{paymentMark(item.id)}}</view><view class="shop-channel-copy"><text>{{item.label}}</text><text v-if="item.id==='unionpay'">银联安全收银</text><text v-else-if="item.id==='bank-card'">支持储蓄卡和信用卡</text></view><image :src="channel===item.id?'/static/common/icon-radio-checked.png':'/static/common/icon-radio-unchecked.png'" mode="aspectFit"/></button></view><text v-if="channels.length===1" class="shop-payment-note">该订单仅支持{{channels[0].label}}。</text><text v-if="message" class="shop-error">{{message}}</text><button v-if="attemptId" class="shop-secondary" :disabled="busy" @click="check">查询支付结果</button><button class="shop-link" @click="details">查看订单</button></template></view><view v-if="order" class="shop-footer"><button class="shop-primary" style="width:100%" :disabled="busy||!!attemptId||!channel||!order.allowedActions.includes('pay')||expired" @click="pay">{{busy?'处理中…':'确认支付'}}</button></view></view></template>
<script setup>
import {ref,computed} from 'vue'
import {onLoad,onShow,onUnload} from '@dcloudio/uni-app'
import {useAuth} from '../../composables/useAuth'
import {getCommerceOrder,getPaymentChannels,startPayment,queryPayment,commerceRequestKey,getPendingPayment} from '../../services/commerce'
import {money} from '../../features/exclusive/format'
import BusinessPageHeader from '../../components/BusinessPageHeader.vue'
import FeaturePageState from '../../components/FeaturePageState.vue'
useAuth();let id='',active=true,timer,offset=0,loaded=false,paymentKey='',paymentChannel='';const order=ref(null),channels=ref([]),channel=ref(''),status=ref('loading'),error=ref(''),busy=ref(false),message=ref(''),attemptId=ref(''),now=ref(Date.now()),expired=computed(()=>order.value&&Date.parse(order.value.expiresAt)<=now.value+offset),remaining=computed(()=>{const sec=Math.max(0,Math.ceil((Date.parse(order.value?.expiresAt)-now.value-offset)/1000));return `${Math.floor(sec/60)}分${sec%60}秒`})
async function load(){status.value='loading';try{const [result,ways]=await Promise.all([getCommerceOrder(id),getPaymentChannels(id)]);if(!active)return;order.value=result.order;const pending=getPendingPayment(id);if(pending){attemptId.value=pending.attemptId||'';channel.value=pending.channel;paymentKey=pending.key;paymentChannel=pending.channel}offset=Date.parse(result.serverTime||new Date().toISOString())-Date.now();channels.value=ways.items;if(!channel.value)channel.value=ways.items[0]?.id||'';status.value='ready'}catch(e){if(active){error.value=e.message;status.value='error'}}}
function details(){uni.redirectTo({url:`/pages/order/detail?id=${encodeURIComponent(id)}`})}
async function check(){if(busy.value||!attemptId.value)return;busy.value=true;try{const result=await queryPayment(attemptId.value);if(!active)return;if(result.status==='SUCCEEDED'){uni.showToast({title:'支付成功',icon:'success'});details()}else if(result.status==='PROCESSING')message.value='支付处理中，请稍后查询';else{message.value=result.status==='CANCELLED'?'支付已取消，可重新发起':'支付失败，请重新选择支付方式';attemptId.value='';paymentKey='';await load()}}catch(e){if(active)message.value=e.message}finally{if(active)busy.value=false}}
async function pay(){if(busy.value||attemptId.value)return;busy.value=true;message.value='';if(!paymentKey||paymentChannel!==channel.value){paymentKey=commerceRequestKey();paymentChannel=channel.value}try{const attempt=await startPayment(id,channel.value,paymentKey);if(!active)return;attemptId.value=attempt.id}catch(e){if(active)message.value=e.message}finally{if(active)busy.value=false}if(attemptId.value)await check()}
const paymentMark=id=>({wechat:'微',alipay:'支',unionpay:'银', 'bank-card':'卡'}[id]||'付')
onLoad(q=>{id=q.orderId||'';loaded=true;timer=setInterval(()=>{now.value=Date.now()},1000)});onShow(()=>{if(loaded){load();if(attemptId.value)check()}});onUnload(()=>{active=false;clearInterval(timer)})
</script><style>@import '../../styles/commerce.css';</style>
